CREATE TABLE "Settings" (id TEXT PRIMARY KEY, machineId TEXT NOT NULL, activatedAt DATETIME NOT NULL, lastCheckedAt DATETIME NOT NULL, unlocked INTEGER NOT NULL DEFAULT 0, tokenSecret TEXT, lastSeenDate DATETIME, licenseType TEXT NOT NULL DEFAULT 'trial', trialDays INTEGER NOT NULL DEFAULT 14, licenseStartedAt DATETIME, licenseExpiresAt DATETIME, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL);
CREATE UNIQUE INDEX Settings_machineId_key ON Settings(machineId);

CREATE TABLE "Tenant" (id TEXT PRIMARY KEY, name TEXT NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE "User" (id TEXT PRIMARY KEY, tenantId TEXT NOT NULL, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, passwordHash TEXT NOT NULL, isActive INTEGER NOT NULL DEFAULT 1, mustChangePassword INTEGER NOT NULL DEFAULT 0, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, FOREIGN KEY (tenantId) REFERENCES Tenant(id) ON DELETE CASCADE);
CREATE TABLE "Role" (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, isSystem INTEGER NOT NULL DEFAULT 0, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE "Permission" (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, resource TEXT NOT NULL, action TEXT NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE "UserRole" (userId TEXT NOT NULL, roleId TEXT NOT NULL, PRIMARY KEY (userId, roleId), FOREIGN KEY (userId) REFERENCES User(id) ON DELETE CASCADE, FOREIGN KEY (roleId) REFERENCES Role(id) ON DELETE CASCADE);
CREATE TABLE "RolePermission" (roleId TEXT NOT NULL, permissionId TEXT NOT NULL, PRIMARY KEY (roleId, permissionId), FOREIGN KEY (roleId) REFERENCES Role(id) ON DELETE CASCADE, FOREIGN KEY (permissionId) REFERENCES Permission(id) ON DELETE CASCADE);
CREATE TABLE "TenantFeature" (tenantId TEXT NOT NULL, featureKey TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, PRIMARY KEY (tenantId, featureKey), FOREIGN KEY (tenantId) REFERENCES Tenant(id) ON DELETE CASCADE);

CREATE TABLE "Client" (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT, address TEXT, notes TEXT, isActive INTEGER NOT NULL DEFAULT 1, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX idx_client_name ON Client(name);
CREATE INDEX idx_client_phone ON Client(phone);
CREATE TABLE "Employee" (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT, isActive INTEGER NOT NULL DEFAULT 1, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX idx_employee_name ON Employee(name);

CREATE TABLE "Shift" (id TEXT PRIMARY KEY, number INTEGER NOT NULL UNIQUE, openedBy TEXT NOT NULL, openingCash REAL NOT NULL DEFAULT 0, openedAt TEXT NOT NULL, closedAt TEXT, countedCash REAL, expectedCash REAL, difference REAL, notes TEXT, status TEXT NOT NULL DEFAULT 'open', FOREIGN KEY (openedBy) REFERENCES User(id));
CREATE TABLE "ExpenseCategory" (id TEXT PRIMARY KEY, name TEXT NOT NULL, isActive INTEGER NOT NULL DEFAULT 1, createdAt TEXT NOT NULL);
CREATE TABLE "Expense" (id TEXT PRIMARY KEY, categoryId TEXT NOT NULL, amount REAL NOT NULL, paymentMethod TEXT NOT NULL DEFAULT 'cash', date TEXT NOT NULL, description TEXT, reference TEXT, shiftId TEXT, createdBy TEXT, createdAt TEXT NOT NULL, FOREIGN KEY (categoryId) REFERENCES ExpenseCategory(id), FOREIGN KEY (shiftId) REFERENCES Shift(id), FOREIGN KEY (createdBy) REFERENCES User(id), CHECK (amount > 0), CHECK (paymentMethod IN ('cash', 'wallet', 'instapay')));
CREATE INDEX idx_expenses_shift ON Expense(shiftId);
CREATE TABLE "PrinterSetting" (key TEXT PRIMARY KEY, value TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE "AuditLog" (id TEXT PRIMARY KEY, actorUserId TEXT, action TEXT NOT NULL, entityType TEXT NOT NULL, entityId TEXT, summary TEXT NOT NULL, beforeJson TEXT, afterJson TEXT, createdAt TEXT NOT NULL, FOREIGN KEY (actorUserId) REFERENCES User(id));
CREATE INDEX idx_audit_log_entity ON AuditLog(entityType, entityId);
CREATE TABLE "CashDrawerMovement" (id TEXT PRIMARY KEY, shiftId TEXT NOT NULL, type TEXT NOT NULL, amount REAL NOT NULL, reason TEXT NOT NULL, createdBy TEXT NOT NULL, createdAt TEXT NOT NULL, FOREIGN KEY (shiftId) REFERENCES Shift(id), FOREIGN KEY (createdBy) REFERENCES User(id));

CREATE TABLE "DryCleanOrder" (id TEXT PRIMARY KEY, orderNumber INTEGER NOT NULL UNIQUE, clientId TEXT NOT NULL, deliveryAddress TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'received', receivedByEmployeeId TEXT NOT NULL, assignedIronerId TEXT, deliveredByEmployeeId TEXT, receivedAt TEXT NOT NULL, expectedDeliveryAt TEXT, processingStartedAt TEXT, completedAt TEXT, readyAt TEXT, deliveredAt TEXT, cancelledAt TEXT, cancelledReason TEXT, subtotal REAL NOT NULL DEFAULT 0, discountAmount REAL NOT NULL DEFAULT 0, totalAmount REAL NOT NULL DEFAULT 0, notes TEXT, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, FOREIGN KEY (clientId) REFERENCES Client(id), FOREIGN KEY (receivedByEmployeeId) REFERENCES Employee(id), FOREIGN KEY (assignedIronerId) REFERENCES Employee(id), FOREIGN KEY (deliveredByEmployeeId) REFERENCES Employee(id), CHECK (status IN ('received', 'processing', 'needs_review', 'ready', 'delivered', 'cancelled')), CHECK (subtotal >= 0), CHECK (discountAmount >= 0), CHECK (totalAmount >= 0));
CREATE INDEX idx_dry_clean_order_client ON DryCleanOrder(clientId, createdAt);
CREATE INDEX idx_dry_clean_order_status ON DryCleanOrder(status, expectedDeliveryAt);
CREATE TABLE "DryCleanOrderLine" (id TEXT PRIMARY KEY, orderId TEXT NOT NULL, garmentType TEXT NOT NULL, serviceDescription TEXT NOT NULL, quantity INTEGER NOT NULL, colorOrDescription TEXT, conditionBefore TEXT, damageNotes TEXT, processingNotes TEXT, unitPrice REAL NOT NULL, lineTotal REAL NOT NULL, countsForProductivity INTEGER NOT NULL DEFAULT 1, isManualEntry INTEGER NOT NULL DEFAULT 1, FOREIGN KEY (orderId) REFERENCES DryCleanOrder(id) ON DELETE CASCADE, CHECK (quantity > 0), CHECK (unitPrice >= 0), CHECK (lineTotal >= 0));
CREATE INDEX idx_dry_clean_line_order ON DryCleanOrderLine(orderId);
CREATE TABLE "DryCleanOrderStatusHistory" (id TEXT PRIMARY KEY, orderId TEXT NOT NULL, fromStatus TEXT, toStatus TEXT NOT NULL, changedByUserId TEXT NOT NULL, notes TEXT, createdAt TEXT NOT NULL, FOREIGN KEY (orderId) REFERENCES DryCleanOrder(id) ON DELETE CASCADE, FOREIGN KEY (changedByUserId) REFERENCES User(id));
CREATE INDEX idx_dry_clean_status_history_order ON DryCleanOrderStatusHistory(orderId, createdAt);
CREATE TABLE "DryCleanOrderPayment" (id TEXT PRIMARY KEY, orderId TEXT NOT NULL, amount REAL NOT NULL, paymentMethod TEXT NOT NULL, paidAt TEXT NOT NULL, createdByUserId TEXT NOT NULL, reference TEXT, notes TEXT, FOREIGN KEY (orderId) REFERENCES DryCleanOrder(id) ON DELETE RESTRICT, FOREIGN KEY (createdByUserId) REFERENCES User(id), CHECK (amount > 0), CHECK (paymentMethod IN ('cash', 'wallet', 'instapay')));
CREATE INDEX idx_dry_clean_payment_order ON DryCleanOrderPayment(orderId, paidAt);
CREATE TABLE "DryCleanProductivity" (id TEXT PRIMARY KEY, orderId TEXT NOT NULL UNIQUE, ironerEmployeeId TEXT NOT NULL, countedQuantity INTEGER NOT NULL, completedAt TEXT NOT NULL, createdAt TEXT NOT NULL, FOREIGN KEY (orderId) REFERENCES DryCleanOrder(id) ON DELETE RESTRICT, FOREIGN KEY (ironerEmployeeId) REFERENCES Employee(id), CHECK (countedQuantity >= 0));
CREATE INDEX idx_dry_clean_productivity_employee ON DryCleanProductivity(ironerEmployeeId, completedAt);

